INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12837, 16620, 'tt0093378', NULL, 'La Bamba', 'La Bamba', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/6Znulqtc7cdqlUC69HGf26Ef5fi.jpg', 'https://image.tmdb.org/t/p/original/jXDanAOPM6gmypt72WlkZwrPuK0.jpg', 'Los Angeles teenager Ritchie Valens becomes an overnight rock ''n'' roll success in 1958, thanks to a love ballad called "Donna" that he wrote for his girlfriend. But as his star rises, Valens has conflicts with his jealous brother, Bob, and becomes haunted by a recurring nightmare of a plane crash just as he begins his first national tour alongside Buddy Holly.', NULL, NULL, 4.8648, 7.28, 0, 1.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12838, 15379, 'tt0087727', NULL, 'Missing in Action', 'Missing in Action', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/nBrDcnNQca88ed1gRwZ1Q5cjNxE.jpg', 'https://image.tmdb.org/t/p/original/8GVHeU77wFodIkwetIufkTVPgOF.jpg', 'American servicemen are still being held captive in Vietnam and it''s up to one man to bring them home in this blistering, fast-paced action/adventure starring martial arts superstar Chuck Norris. Following a daring escape from a Vietnamese POW camp, Special Forces Colonel James Braddock (Norris) is on a mission to locate and save remaining MIAs.', NULL, NULL, 5.1818, 5.894, 0, 1.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
