INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12845, 75983, 'tt0885523', NULL, 'The Rules of the Game', '新家法', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/rWPUbU78DDAowWjMuYDSfd3REaA.jpg', 'https://image.tmdb.org/t/p/original/cgVxMuvkd1CxJxBXH3U3IPVtfNx.jpg', 'David Chow infiltrates a gang to take revenge on a triad boss, Shing. His close friend, Chun, was beaten so brutally by Shing that he was left paralyzed. To add to his pain, David’s crush, Ann, chooses to date Shing instead of him. Therefore, David joins Shing’s gang under the pretense of seeking wealth and a better future. Secretly, he plans his revenge against Shing.', NULL, NULL, 1.3059, 4.9, 0, 9.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
