INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12848, 44269, 'tt1587877', NULL, 'All That Glitters', 'Tout ce qui Brille', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/qDVRDQOvM4aE4UgxMFlS94WvoEo.jpg', 'https://image.tmdb.org/t/p/original/twXMFXN7QFvKtvw97Vs2OpmpueA.jpg', 'Best friends Ely and Lila share everything together, including their dream of a life beyond the Paris suburb they''ve lived in since childhood. One night they venture into the capital and meet a pair of wealthy young friends at a night club. Ashamed of their working-class background, and seeing an opportunity to escape, Ely and Lila begin to lie their way into this glamorous new world. Falling deeper into their web of lies, the young women begin to lose sight of themselves as their friendship is pushed to the limit.', NULL, NULL, 1.3747, 6.343, 0, 9.015, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12849, 968438, 'tt15521050', NULL, 'Love & Gelato', 'Love & Gelato', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/AbGBTH3bWaiJpjCOJ9RSoQ9NPRT.jpg', 'https://image.tmdb.org/t/p/original/x71agtfuKEm7B5eJg5K8Ey9G9GM.jpg', 'Lina is about to graduate high school and has her sights set on her future at MIT. But when her mom gets sick, she encourages Lina to follow in her footsteps and have “the summer of a lifetime” in Rome. Using her mom’s old diary as a guide, she explores the romantic and magical city, where she just might find love... and gelato, of course.', NULL, NULL, 2.3506, 5.409, 0, 10.6, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12850, 12408, 'tt0791303', NULL, 'Genova', 'Genova', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/sxYarCXOudBzSyFbBBNt723R7q3.jpg', 'https://image.tmdb.org/t/p/original/oOzl6SnWieiYR7zwKHaoYDuciEm.jpg', 'A man moves his two daughters to Italy after their mother dies in a car accident, in order to revitalize their lives. Genoa changes all three of them as the youngest daughter starts to see the ghost of her mother, while the older one discovers her sexuality.', NULL, NULL, 1.1149, 5.654, 0, 9.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12851, 509967, 'tt8106534', NULL, '6 Underground', '6 Underground', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/lnWkyG3LLgbbrIEeyl5mK5VRFe4.jpg', 'https://image.tmdb.org/t/p/original/eFw5YSorHidsajLTayo1noueIxI.jpg', 'After faking his death, a tech billionaire recruits a team of international operatives for a bold and bloody mission to take down a brutal dictator.', NULL, NULL, 9.1953, 6.33, 0, 8.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12852, 24188, 'tt0056512', NULL, 'Il Sorpasso', 'Il sorpasso', 'movie', 1962, 'https://image.tmdb.org/t/p/w500/4h1ckrJQVcQYjeOkqS8i9BqZ9MI.jpg', 'https://image.tmdb.org/t/p/original/uUrV5KSjnZx47Dq7e6STr73iN4N.jpg', 'Roberto, a shy law student in Rome, meets Bruno, a forty-year-old exuberant, capricious man, who takes him for a drive through the Roman and Tuscany countries in the summer. When their journey starts to blend into their daily lives though, the pair’s newfound friendship is tested.', NULL, NULL, 2.9392, 8.228, 0, 9.03, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12853, 9520, 'tt0430674', NULL, 'The Thief Lord', 'The Thief Lord', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/mLTON0o7tEk37UQMcnIWpngq1ZK.jpg', 'https://image.tmdb.org/t/p/original/lwsoLKyGaZbmLg3ZC9mPLjWlfqQ.jpg', 'A tale about two young boys, Prosper and Bo, who flee to Venice after being orphaned and dumped in the care of a cruel auntie. Hiding in the canals and alleyways of the city, the boys are befriended by a gang of young urchins and their enigmatic leader, the Thief Lord. From their home base of an old cinema theater, the children steal from the rich to support themselves and soon capture the interest of a bumbling detective. However, a greater threat to the children is something from a forgotten past - a beautiful magical treasure with the power to spin time itself', NULL, NULL, 2.3195, 5.96, 0, 8.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12854, 2503, 'tt0440963', NULL, 'The Bourne Ultimatum', 'The Bourne Ultimatum', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/15rMz5MRXFp7CP4VxhjYw4y0FUn.jpg', 'https://image.tmdb.org/t/p/original/qiBILuWhv7ipF0pxiEqIJdkQzj8.jpg', 'Bourne is brought out of hiding once again by reporter Simon Ross who is trying to unveil Operation Blackbriar, an upgrade to Project Treadstone, in a series of newspaper columns. Information from the reporter stirs a new set of memories, and Bourne must finally uncover his dark past while dodging The Company''s best efforts to eradicate him.', NULL, NULL, 13.0667, 7.442, 0, 8.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
