INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12856, 25403, 'tt0109382', NULL, 'Caro diario', 'Caro diario', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/fpuOq1YN7LHjctGFniOK8OPnwgs.jpg', 'https://image.tmdb.org/t/p/original/dsMqUvdYGeXSky9cQO26JJOhFZa.jpg', 'Nanni Moretti recounts in his diary three slice-of-life stories marked by a dry, ironic gaze: in the first, he rides his Vespa through a deserted, sun-drenched summertime Rome; in the second, he visits a reclusive friend on an island, who ropes him into an impromptu journey between islets in search of quiet; and in the last, he finds himself grappling with an unknown illness.', NULL, NULL, 1.8171, 7.3, 0, 9.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
