INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12890, 147941, 'tt0052718', NULL, 'Curse of the Undead', 'Curse of the Undead', 'movie', 1959, 'https://image.tmdb.org/t/p/w500/jlWWAtiO1GBzcgWxPET6Evyc1hC.jpg', 'https://image.tmdb.org/t/p/original/vNr5oRrDRY7tIefSJiDaLaU2WIs.jpg', 'A mysterious epidemic has struck an Old West frontier town and young girls are falling deathly ill. Doc Carter, his lovely daughter Dolores, and preacher Dan Young have their hands full caring for the infirm. When one of the patients dies unexpectedly, Dan notices two puncture wounds on her neck. His investigation leads him to the strange gunslinger Drake Robey, who always seems to be slower on the draw than his opponents, but who—despite being outdrawn, and even shot—always manages to survive these deadly encounters. Dan soon discovers that Drake also has an aversion to crucifixes, sleeps in coffins, and cannot tolerate sunlight...', NULL, NULL, 1.6269, 5.6, 0, 6.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12891, NULL, NULL, 141547, 'Evil West', 'Evil West', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4udq.jpg', NULL, 'A dark menace consumes the Old West. In solo or coop, fight with style in visceral, explosive combat against bloodthirsty monstrosities. Eradicate the vampiric hordes with your lightning-fueled gauntlet and become a Wild West Superhero.

In visceral, explosive combat, unleash hell with your firearms, lightning-fueled gauntlet and gadgets. Kill bloodthirsty monstrosities in style as a lone hunter or in co-op with a friend. Explore and fight in a narrative-driven campaign while upgrading your weapons and hunting tools. Unlock new perks to evolve your monster-slaying mastery, crafting your own playstyle to defeat the supernatural hordes.', 'https://www.igdb.com/games/evil-west', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, NULL, 0, 8.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12892, 46429, 'tt0829176', NULL, 'Gallowwalkers', 'Gallowwalkers', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/cGBmTiNomYCk6Lr4Gkhbssg0m82.jpg', 'https://image.tmdb.org/t/p/original/cBIGV9LYgJtb3xHETpgBgN7Mi3F.jpg', 'When a nun broke her covenant with God to save the life of  her unborn son, Aman, he was cursed for life. As an adult, Aman has killed those who have crossed him. But his curse brings his victims back to life and they pursue him for revenge, so Aman enlists a young gunman to fight by his side against his undead victims.', NULL, NULL, 3.388, 4.809, 0, 6.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
