INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12923, 33880, 'tt1695360', NULL, 'The Legend of Korra', 'The Legend of Korra', 'tv', 2012, 'https://image.tmdb.org/t/p/w500/dZgYvSfuh1YHDrJuILlVQ5oA2hF.jpg', 'https://image.tmdb.org/t/p/original/hmrNfrUl3FFaymDj6Iw5oKQjIs2.jpg', 'Avatar Korra, a headstrong, rebellious, feisty young woman who continually challenges and breaks with tradition, is on her quest to become a fully realized Avatar. In this story, the Avatar struggles to find balance within herself.', NULL, NULL, 48.0928, 8.215, 0, 8.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12924, 174675, 'tt2317225', NULL, 'The Machine', 'The Machine', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/nNHAZaTrFVOjwLhkMYm4syUjNw8.jpg', 'https://image.tmdb.org/t/p/original/3CcZRO5UMQwIA2f3U6bEnpjpegf.jpg', 'Already deep into a second Cold War, Britain’s Ministry of Defense seeks a game-changing weapon. Programmer Vincent McCarthy unwittingly provides an answer in The Machine, a super-strong human cyborg. When a programming bug causes the prototype to decimate his lab, McCarthy takes his obsessive efforts underground, far away from inquisitive eyes.', NULL, NULL, 4.077, 5.891, 0, 8.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12925, 292523, 'tt0063381', NULL, 'Whistle and I''ll Come to You', 'Whistle and I''ll Come to You', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/4xEEqlG2vLQvd9s8ljUBHD1OPaK.jpg', 'https://image.tmdb.org/t/p/original/rdv5d9n5lluVWHcfpeyGCejWCF2.jpg', 'A university professor, confident that everything which occurs in life has a rational explanation, finds his beliefs severely challenged when, during a vacation to a remote coastal village in Norfolk, he blows through an ancient whistle discovered on a beach, awakening horrors beyond human understanding.', NULL, NULL, 0.7584, 6.556, 0, 2.015, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12926, 606666, 'tt0385180', NULL, 'The Psychic Parrot', 'The Psychic Parrot', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/z19qukB96X6O5R6gl2o4pTtgzli.jpg', NULL, 'An ordinary middle class suburban couple sees a celebrity parrot on TV who supposedly foretells the future. The parrot predicts the world is coming to an end. The couple are initially shocked, and then decide to make the most of the time they have left. They get dressed up and decide to celebrate as if it was New Year''s Eve, since the world is supposed to end at midnight. On TV, it is shown that all the important people of the world are selected and sent to the moon in a space ship so they can escape the earth''s destruction. As midnight approaches the couple gamely prepares to toast their demise, but midnight comes and the world doesn''t end. A special comes on TV and the parrot explains he made a mistake. As he starts to correct himself, the moon blows up. All of the scenes on TV are animated cartoons. The scenes with the husband and wife are filmed live actors.', NULL, NULL, 0.5463, 6.5, 0, 1.03, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
