INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12940, 4920, 'tt0914387', NULL, 'Damages', 'Damages', 'tv', 2007, 'https://image.tmdb.org/t/p/w500/bowEbW8Q3Oc02BvHBKTL5gWv9Nx.jpg', 'https://image.tmdb.org/t/p/original/lAsz5DYQpXcOONSVuZdZIrtZoIv.jpg', 'Damages is an American legal thriller television series created by the writing and production trio of Daniel Zelman and brothers Glenn and Todd A. Kessler. The plot revolves around the brilliant, ruthless lawyer Patty Hewes and her protégée, recent law school graduate Ellen Parsons. Each season features a major case that Hewes and her firm take on, while also examining a chapter of the complicated relationship between Ellen and Patty. The first two seasons center around the law firm Hewes & Associates. Later seasons center more on Patty and Ellen''s relationship as Ellen begins to distance herself from Hewes & Associates and begins an independent career.', NULL, NULL, 37.9871, 7.478, 0, 1.03, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12941, 36047, 'tt0163676', NULL, 'The In Crowd', 'The In Crowd', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/j77l405846qiLb8RGb1egu7ON3r.jpg', 'https://image.tmdb.org/t/p/original/jBeGCBNfkVsKrFajGETIoscJRvK.jpg', 'A mentally disturbed young woman takes a job at a posh country club and falls in with a clique of wealthy college kids where she''s taken under the wing of the clique''s twisted leader, who harbors some dark secrets too terrifying to tell.', NULL, NULL, 1.7102, 4.653, 0, 1.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12942, NULL, NULL, 119304, 'Spiritfarer', 'Spiritfarer', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fe7.jpg', NULL, 'Spiritfarer is a cozy management game about dying. You play Stella, ferrymaster to the deceased, a Spiritfarer. Build a boat to explore the world, then befriend and care for spirits before finally releasing them into the afterlife. Farm, mine, fish, harvest, cook, and craft your way across mystical seas. Join the adventure as Daffodil the cat, in two-player cooperative play. Spend relaxing quality time with your spirit passengers, create lasting memories, and, ultimately, learn how to say goodbye to your cherished friends. What will you leave behind?', 'https://www.igdb.com/games/spiritfarer', '["Google Stadia", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12943, 41659, 'tt0107630', NULL, 'My Life', 'My Life', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/eF8wNMMqY3kukUTTAVXLLx94UhB.jpg', 'https://image.tmdb.org/t/p/original/5ccAivPcFEJazxwZZnr5QOGNcz6.jpg', 'It seems that Bob Jones has everything a man could want, namely a fulfilling job and a beautiful, pregnant wife, Gail. But Bob''s life is turned upside-down when he is diagnosed with cancer and given four months to live -- not even enough time to see his first child''s birth. To cleanse himself of demons in his remaining days, Bob makes a video diary, hoping to pass along some wisdom to his future child. Along the way, he discovers a lot about himself.', NULL, NULL, 2.3819, 6.672, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12944, 33545, 'tt0098328', NULL, 'The Siege of Firebase Gloria', 'The Siege of Firebase Gloria', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/cAN1OLcfRt6ONQOLGGGEcAtC6tn.jpg', 'https://image.tmdb.org/t/p/original/n2K8BsXiafvIBaEUsG7UQfDyffT.jpg', 'A Marine patrol stops at Firebase Gloria at the start of the Tet Offensive during the Vietnam war. With the firebase attacked, the patrol remains to help defend it.', NULL, NULL, 1.6557, 5.6, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12945, 20181, 'tt0970462', NULL, 'Tunnel Rats', 'Tunnel Rats', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/cm3a0SeO6DvoMbSlsZZSfINohbP.jpg', 'https://image.tmdb.org/t/p/original/mr7RYg69jt5KcC7G218Bxp68kzN.jpg', 'During the Vietnam War [1959-1975] a special US combat unit is sent out to hunt and kill the Viet Cong soldiers in a man-to-man combat in the endless tunnels underneath the jungle of Vietnam. Suicide squads of a special kind.', NULL, NULL, 2.8057, 4.917, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12946, 10142, 'tt0097027', NULL, 'Casualties of War', 'Casualties of War', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/3SerZUDoU9TMCXMsQqiXvSWm0uL.jpg', 'https://image.tmdb.org/t/p/original/asg9dWAGNVjgztjOIhbaWQIYqrr.jpg', 'During the Vietnam War, a soldier finds himself the outsider of his own squad when they unnecessarily kidnap a female villager.', NULL, NULL, 6.0002, 7.2, 0, 3.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12947, 27281, 'tt0114048', NULL, 'Operation Dumbo Drop', 'Operation Dumbo Drop', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/qIJlpbMCKg9O1C7gaiyDFaUWf9b.jpg', 'https://image.tmdb.org/t/p/original/zPpB979cGcFKNIzW5ohiG6WEf7s.jpg', 'Five Green Berets stationed in Vietnam in 1968 grudgingly undertake the mission of a lifetime -- to secretly transport an 8,000-pound elephant through 200 miles of rough jungle terrain. High jinks prevail when Capt. Sam Cahill promises the Montagnard villagers of Dak Nhe that he''ll replace their prized elephant in time for an important ritual. But for Capt. T.C. Doyle, the mission becomes a jumbo-sized headache!', NULL, NULL, 3.0954, 5.191, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12948, 57976, 'tt0145046', NULL, 'Little Dieter Needs to Fly', 'Little Dieter Needs to Fly', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/2sLpyYytu0Dbymzs3skxOCRHKkl.jpg', 'https://image.tmdb.org/t/p/original/o3cMdKm2NN2TtF9Gx7epPODNUBy.jpg', 'Three decades after German-American pilot Dieter Dengler was shot down over Laos, he returns to the places where he was held prisoner during the early years of the Vietnam War. Accompanied by director Werner Herzog, Dengler describes in unusually candid detail his captivity, the friendships he made, and his daring escape. Not willing to stop there, Herzog even persuades his subject to re-enact certain tortures, with the help of some willing local villagers.', NULL, NULL, 1.1332, 7.47, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12949, 41733, 'tt1231583', NULL, 'Due Date', 'Due Date', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/sBxWS09pOOyXZ0dcnqfqqCAQGan.jpg', 'https://image.tmdb.org/t/p/original/naV4PO7ftzNThYKGX44F8vRY2z3.jpg', 'Peter Highman must scramble across the US in five days to be present for the birth of his first child. He gets off to a bad start when his wallet and luggage are stolen, and put on the ''no-fly'' list. Peter embarks on a terrifying journey when he accepts a ride from an actor.', NULL, NULL, 8.594, 6.392, 0, 1.03, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
