INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12951, 324849, 'tt4116284', NULL, 'The Lego Batman Movie', 'The Lego Batman Movie', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/e1TliRWOdXQ73pRunbpFiGst6Kd.jpg', 'https://image.tmdb.org/t/p/original/rWYtghaUJSDvQm4jmXiCPXBHUdQ.jpg', 'A cooler-than-ever Bruce Wayne must deal with the usual suspects as they plan to rule Gotham City, while discovering that he has accidentally adopted a teenage orphan who wishes to become his sidekick.', NULL, NULL, 16.8632, 7.259, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12952, 49538, 'tt1270798', NULL, 'X-Men: First Class', 'X-Men: First Class', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/hNEokmUke0dazoBhttFN0o3L7Xv.jpg', 'https://image.tmdb.org/t/p/original/yhp5Pt4GugkCs5mz63qWz5khHXe.jpg', 'Before Charles Xavier and Erik Lensherr took the names Professor X and Magneto, they were two young men discovering their powers for the first time. Before they were arch-enemies, they were closest of friends, working together with other mutants (some familiar, some new), to stop the greatest threat the world has ever known.', NULL, NULL, 1.0861, 7.304, 0, 1.02, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12953, 17436, 'tt0865554', NULL, 'The Informers', 'The Informers', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/yiXkvghbkYMQ3iMyhiI08GgtonC.jpg', 'https://image.tmdb.org/t/p/original/3HJBIGN4ZjX6xwNQsM9GlvZgZCX.jpg', 'A collection of intersecting short stories set in early 1980s Los Angeles, depicts a week in the lives of an assortment of socially alienated, mainly well-off characters who numb their sense of emptiness with casual sex, violence, and drugs.', NULL, NULL, 4.4418, 4.752, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12954, 938262, 'tt0759709', NULL, 'The Secret of Lost River', 'The Secret of Lost River', 'movie', 1915, NULL, NULL, 'Pierre Vignol, an artist wintering in Arizona, is bitten by a snake. He is taken by his friend, Tom Hornby, to Padre Francisco, who prescribes for the bite. Pierre, at the request of Tom, returns to his cabin and Tom takes care of him. Later Tom discovers a tube in Lost River. This proves to be a painting and Pierre takes it to Padre Francisco. The Padre reads him an interesting history of Fr. Bartolomeo. founder of the Mission, and of how the painting came to be discovered in Lost River, for it had been thrown there by a monk when the Mission was attacked by the Indians, owing to the abduction of the Chief''s daughter by a villainous Spaniard. Tom takes the painting to New York where he sells it and gives the money to the wife of Tom, who has been too poor to bring her and the baby to Arizona.', NULL, NULL, 0.6125, 0.0, 0, 1.07, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12955, 474751, 'tt12814750', NULL, 'Neon Parallel 1996', 'Neon Parallel 1996', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/jKGB5O31P7OpN0KXo9WE9Ovu0wm.jpg', 'https://image.tmdb.org/t/p/original/uBNkg4byips1dYFxTjcLA1L25Kd.jpg', 'Part live-action footage, video game sequences, simulated chat, poetic voiceover and virtual landscape, Neon Parallel 1996 is in Rafman’s own words an attempt at creating a “lost vaporwave classic.”', NULL, NULL, 0.6473, 6.5, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12956, 2241, 'tt0177242', NULL, 'Sonnenallee', 'Sonnenallee', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/lkoK4EVQiIx60a65BoR2HGpiw8g.jpg', 'https://image.tmdb.org/t/p/original/qg6s5pLyOdCalXBavcbIXzqwd0n.jpg', 'A group of kids grow up on the short, wrong (east) side of the Sonnenallee in Berlin, right next to one of the few border crossings between East and West reserved for German citizens. The antics of these kids, their families, of the "West German" friends and relatives who come to visit, and of the East German border guards, all serve to illustrate the absurdity of everyday life on the Sonnenallee, and therefore throughout the former East Germany.', NULL, NULL, 2.2603, 6.696, 0, 8.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12957, 466557, 'tt5913968', NULL, 'Porcupine Lake', 'Porcupine Lake', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/hVXGkiTFCYai7LQaMOc7YQ6aeme.jpg', 'https://image.tmdb.org/t/p/original/gVtcOaewt4jC7ovKisrtHMTW2X7.jpg', 'During a hot and hazy summertime in northern Ontario, 13-year-old Bea wants a best friend more than anything else, but when she meets boisterous Kate, she gets more than she imagined. A story of bravery, small-town summer love, and the secret world of girls.', NULL, NULL, 1.4767, 5.243, 0, 8.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
