INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12959, NULL, NULL, 7331, 'Uncharted 4: A Thief''s End', 'Uncharted 4: A Thief''s End', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7h.jpg', NULL, 'Several years after his last adventure, retired fortune hunter, Nathan Drake, is forced back into the world of thieves. With the stakes much more personal, Drake embarks on a globe-trotting journey in pursuit of a historical conspiracy behind a fabled pirate treasure. His greatest adventure will test his physical limits, his resolve, and ultimately what he''s willing to sacrifice to save the ones he loves.', 'https://www.igdb.com/games/uncharted-4-a-thief-s-end', '["PlayStation 4"]', NULL, NULL, 0, 1.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
