INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12961, 4886, 'tt0037515', NULL, 'And Then There Were None', 'And Then There Were None', 'movie', 1945, 'https://image.tmdb.org/t/p/w500/maV1jQZ58NZIjwRbdtmRcaW3fZo.jpg', 'https://image.tmdb.org/t/p/original/anyaK6Ab3g2FQyXpTI36rAWRQsw.jpg', 'Ten strangers are summoned to a remote island and while they are waiting for the mysterious host to appear, a recording levels serious accusations at each of the guests. Soon they start being murdered, one by one. As the survivors try to keep their wits, they reach a disturbing conclusion: one of them must be the killer.', NULL, NULL, 2.7894, 7.053, 0, 14.01, '2026-08-31 03:40:48', '2026-08-31 03:40:48');
