UPDATE "recommendations" SET "tmdb_id"=68507, "imdb_id"='tt5607976', "igdb_id"=NULL, "title"='His Dark Materials', "original_title"='His Dark Materials', "media_type"='tv', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/g6tIKGc3f1H5QMz1dcgCwADKpZ7.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/t8KjRqfOqNx14cHLwARjR08bjeb.jpg', "overview"='Lyra is an orphan who lives in a parallel universe in which science, theology and magic are entwined. Her search for a kidnapped friend uncovers a sinister plot involving stolen children and turns into a quest to understand a mysterious phenomenon called Dust. She is later joined on her journey by Will, a boy who possesses a knife that can cut windows between worlds. As she learns the truth about her parents and her prophesied destiny, the two young people are caught up in a war against celestial powers that ranges across many worlds.', "external_url"=NULL, "platforms"=NULL, "popularity"=24.138, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=6.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=431;
UPDATE "recommendations" SET "tmdb_id"=83542, "imdb_id"='tt1371111', "igdb_id"=NULL, "title"='Cloud Atlas', "original_title"='Cloud Atlas', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cHm1lWAok12vwnTHqzprbPTk49q.jpg', "overview"='A set of six nested stories spanning time between the 19th century and a distant post-apocalyptic future. Cloud Atlas explores how the actions and consequences of individual lives impact one another throughout the past, the present and the future. Action, mystery and romance weave through the story as one soul is shaped from a killer into a hero and a single act of kindness ripples across centuries to inspire a revolution in the distant future.  Based on the award winning novel by David Mitchell. Directed by Tom Tykwer and the Wachowskis.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.0047, "vote_average"=6.9, "is_ambiguous"=0, "evidence_score"=3.6035161290322577e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=432;
