UPDATE "recommendations" SET "tmdb_id"=11474, "imdb_id"='tt0080120', "igdb_id"=NULL, "title"='The Warriors', "original_title"='The Warriors', "media_type"='movie', "release_year"=1979, "poster_url"='https://image.tmdb.org/t/p/w500/d6YZpBq4BhQr1K985J3CuL1cA8J.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/i4Fp0AJsqAzbeVQyCoG0adRRfdh.jpg', "overview"='Prominent gang leader Cyrus calls a meeting of New York''s gangs to set aside their turf wars and take over the city. At the meeting, a rival leader kills Cyrus, but a Coney Island gang called the Warriors is wrongly blamed for Cyrus'' death. Before you know it, the cops and every gangbanger in town is hot on the Warriors'' trail.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.0725, "vote_average"=7.68, "is_ambiguous"=0, "evidence_score"=5.88527272727272716e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=639;
UPDATE "recommendations" SET "tmdb_id"=627, "imdb_id"='tt0117951', "igdb_id"=NULL, "title"='Trainspotting', "original_title"='Trainspotting', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/1jUC02qsqS2NxBMFarbIhcQtazV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dkfBKDUIWP1peEszdqK10MkMZCP.jpg', "overview"='Heroin addict Mark Renton stumbles through bad ideas and sobriety attempts with his unreliable friends --Sick Boy, Begbie, Spud and Tommy. He also has an underage girlfriend, Diane, along for the ride. After cleaning up and moving from Edinburgh to London, Mark finds he can''t escape the life he left behind as Begbie and Sick Boy come knocking.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.2431, "vote_average"=7.958, "is_ambiguous"=0, "evidence_score"=8.32864999999999895e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=644;
UPDATE "recommendations" SET "tmdb_id"=11931, "imdb_id"='tt0388125', "igdb_id"=NULL, "title"='In Her Shoes', "original_title"='In Her Shoes', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/gmd2n3TuXewrbINp8Jfhwd5Jw6S.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/yNhmsmCqK6bTl4xUT28fJ1r6f61.jpg', "overview"='Irresponsible party girl Maggie is kicked out of her father''s and stepmother''s home—where she lives for free—and is taken in by her hard-working sister, Philadelphia lawyer Rose. After Maggie''s disruptive ways ruin her sister''s love life, Rose turns her out as well. But when their grandmother, who they never knew existed, comes into their lives, the sisters face some complicated truths about themselves and their family.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.41, "vote_average"=6.22, "is_ambiguous"=0, "evidence_score"=6.5175, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=653;
UPDATE "recommendations" SET "tmdb_id"=21349, "imdb_id"='tt0149691', "igdb_id"=NULL, "title"='Anywhere but Here', "original_title"='Anywhere but Here', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/2DNtxmXkotuaJexU57geTLIPnQf.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/n03FL1Ia88Jq2nV7fz4AJE9utw0.jpg', "overview"='Single mother Adele August is bad with money, and even worse when it comes to making decisions. Her straight-laced daughter, Ann, is a successful high school student with Ivy League aspirations. When Adele decides to pack up and move the two of them from the Midwest to Beverly Hills, Calif., to pursue her dreams of Hollywood success, Ann grows frustrated with her mother''s irresponsible and impulsive ways.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9786, "vote_average"=6.067, "is_ambiguous"=0, "evidence_score"=8.93666666666666742e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=659;
