UPDATE "recommendations" SET "tmdb_id"=7303, "imdb_id"='tt0252076', "igdb_id"=NULL, "title"='Maid in Manhattan', "original_title"='Maid in Manhattan', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/gnEuTYH3jhHxl80QyoPfZjEYd0J.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/l5sD0AK286fBpXyDHRCbtaFMArN.jpg', "overview"='Marisa Ventura is a struggling single mom who works at a posh Manhattan hotel and dreams of a better life for her and her young son. One fateful day, hotel guest and senatorial candidate Christopher Marshall meets Marisa and mistakes her for a wealthy socialite. After an enchanting evening together, the two fall madly in love. But when Marisa''s true identity is revealed, issues of class and social status threaten to separate them. Can two people from very different worlds overcome their differences and live happily ever after?', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8285, "vote_average"=6.135, "is_ambiguous"=0, "evidence_score"=8.0075, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=664;
UPDATE "recommendations" SET "tmdb_id"=10802, "imdb_id"='tt0114436', "igdb_id"=NULL, "title"='Showgirls', "original_title"='Showgirls', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/o4HT3Ap5c99W4FYpdXUtTvxGgPc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jL3G2f8uNCFejJRlIqCzRp8Y7eV.jpg', "overview"='Fresh to Las Vegas with no connections, Nomi Malone takes a job as an exotic dancer. Her talents are quickly noticed by Cristal, a headlining dancer who senses an opportunity to bolster her own act. But Nomi won’t play second fiddle and soon begins her venomous path to the top, ruthlessly backstabbing anyone who gets in her way.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.6109, "vote_average"=5.6, "is_ambiguous"=0, "evidence_score"=26.61, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=665;
UPDATE "recommendations" SET "tmdb_id"=55721, "imdb_id"='tt1478338', "igdb_id"=NULL, "title"='Bridesmaids', "original_title"='Bridesmaids', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/gJtA7hYsBMQ7EM3sPBMUdBfU7a0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1pkpV7a02phSfAPeGVmpHaQd99J.jpg', "overview"='Annie''s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian''s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.4435, "vote_average"=6.509, "is_ambiguous"=0, "evidence_score"=9.94166666666666643e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=666;
UPDATE "recommendations" SET "tmdb_id"=10096, "imdb_id"='tt0337563', "igdb_id"=NULL, "title"='13 Going on 30', "original_title"='13 Going on 30', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', "overview"='After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.0982, "vote_average"=6.777, "is_ambiguous"=0, "evidence_score"=2.60791304347826091e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=667;
UPDATE "recommendations" SET "tmdb_id"=9603, "imdb_id"='tt0112697', "igdb_id"=NULL, "title"='Clueless', "original_title"='Clueless', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/8AwVTcgpTnmeOs4TdTWqcFDXEsA.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/65d0MccsiRSPTVicregKQL8owoo.jpg', "overview"='Shallow, rich and socially successful Cher is at the top of her Beverly Hills high school''s pecking scale. Seeing herself as a matchmaker, Cher first coaxes two teachers into dating each other. Emboldened by her success, she decides to give hopelessly klutzy new student Tai a makeover. When Tai becomes more popular than she is, Cher realizes that her disapproving ex-stepbrother was right about how misguided she was -- and falls for him.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.7261, "vote_average"=7.25, "is_ambiguous"=0, "evidence_score"=43.322, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=668;
UPDATE "recommendations" SET "tmdb_id"=4599, "imdb_id"='tt0350028', "igdb_id"=NULL, "title"='Raising Helen', "original_title"='Raising Helen', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/ubZin4oGXYp6hCn3WU6nrBre62y.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lw5YfNEZaxWo7Q7sn76bLUlyAhi.jpg', "overview"='Helen Harris has a glamorous, big-city life working for one of New York''s hottest modeling agencies. But suddenly her free-spirited life gets turned upside down when she must choose between the life she''s always loved, and the new loves of her life!', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5701, "vote_average"=6.152, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=669;
UPDATE "recommendations" SET "tmdb_id"=8835, "imdb_id"='tt0250494', "igdb_id"=NULL, "title"='Legally Blonde', "original_title"='Legally Blonde', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/9ohlMrJHQqKhfUKh7Zr3JQqHNLZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/viU23X3BIycUFf6TOlm9c7TxLgM.jpg', "overview"='Fashionable sorority queen Elle Woods has it all, but, she wants nothing more than to be Mrs. Warner Huntington III. But he dumps her before heading to Harvard Law School. Elle rallies all of her resources and gets into Harvard, determined to win him back. While there, she figures out that there is more to herself than just good looks.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.9984, "vote_average"=6.82, "is_ambiguous"=0, "evidence_score"=3.25968965517241358e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=672;
