UPDATE "recommendations" SET "tmdb_id"=165, "imdb_id"='tt0096874', "igdb_id"=NULL, "title"='Back to the Future Part II', "original_title"='Back to the Future Part II', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/w6tPctxWAsHoQXeKxxNOT6lYKpx.jpg', "overview"='Marty and Doc are at it again as the time-traveling duo head to 2015 to nip some McFly family woes in the bud. But things go awry thanks to bully Biff Tannen and a pesky sports almanac. In a last-ditch attempt to set things straight, Marty finds himself bound for 1955 and face to face with his teenage parents -- again.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.8751, "vote_average"=7.786, "is_ambiguous"=0, "evidence_score"=11.145, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=780;
