UPDATE "recommendations" SET "tmdb_id"=252, "imdb_id"='tt0067992', "igdb_id"=NULL, "title"='Willy Wonka & the Chocolate Factory', "original_title"='Willy Wonka & the Chocolate Factory', "media_type"='movie', "release_year"=1971, "poster_url"='https://image.tmdb.org/t/p/w500/vmpsZkrs4Uvkp9r1atL8B3frA63.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ko7hMSCtXoJFfpYAIbrowwgH0eq.jpg', "overview"='When eccentric candy man Willy Wonka promises a lifetime supply of sweets and a tour of his chocolate factory to five lucky kids, penniless Charlie Bucket seeks the golden ticket that will make him a winner.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.1022, "vote_average"=7.483, "is_ambiguous"=0, "evidence_score"=19.223125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=861;
UPDATE "recommendations" SET "tmdb_id"=10227, "imdb_id"='tt0062136', "igdb_id"=NULL, "title"='PlayTime', "original_title"='PlayTime', "media_type"='movie', "release_year"=1967, "poster_url"='https://image.tmdb.org/t/p/w500/kQOrS0DLUXYsqPMedM2G6NJcJBq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pKX8G6IN8ZCRvKeHh6ctqoHZl0K.jpg', "overview"='Clumsy Monsieur Hulot finds himself perplexed by the intimidating complexity of a gadget-filled Paris. He attempts to meet with a business contact but soon becomes lost. His roundabout journey parallels that of an American tourist, and as they weave through the inventive urban environment, they intermittently meet, developing an interest in one another. They eventually get together at a chaotic restaurant, along with several other quirky characters.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7514, "vote_average"=7.7, "is_ambiguous"=0, "evidence_score"=2.63780952380952378e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=867;
UPDATE "recommendations" SET "tmdb_id"=427, "imdb_id"='tt0050706', "igdb_id"=NULL, "title"='Mon Oncle', "original_title"='Mon oncle', "media_type"='movie', "release_year"=1958, "poster_url"='https://image.tmdb.org/t/p/w500/wH6RyPiXFy8INLbViVkchLVOmBc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3yYNJeR6JynSE3Y1AfVIJQ6g3UX.jpg', "overview"='Genial, bumbling Monsieur Hulot loves his top-floor apartment in a grimy corner of the city, and cannot fathom why his sister''s family has moved to the suburbs. Their house is an ultra-modern nightmare, which Hulot only visits for the sake of stealing away his rambunctious young nephew. Hulot''s sister, however, wants to win him over to her new way of life, and conspires to set him up with a wife and job.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.3236, "vote_average"=7.427, "is_ambiguous"=0, "evidence_score"=12.36, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=868;
