UPDATE "recommendations" SET "tmdb_id"=490, "imdb_id"='tt0050976', "igdb_id"=NULL, "title"='The Seventh Seal', "original_title"='Det sjunde inseglet', "media_type"='movie', "release_year"=1957, "poster_url"='https://image.tmdb.org/t/p/w500/wcZ21zrOsy0b52AfAF50XpTiv75.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6s2BqtDvp1BMiP70zCDU5OW6hMy.jpg', "overview"='When disillusioned Swedish knight Antonius Block returns home from the Crusades to find his country in the grips of the Black Death, he challenges Death to a chess match for his life. Tormented by the belief that God does not exist, Block sets off on a journey, meeting up with traveling players Jof and his wife, Mia, and becoming determined to evade Death long enough to commit one redemptive act while he still lives.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4995, "vote_average"=8.142, "is_ambiguous"=0, "evidence_score"=4.99438297872340442e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=974;
