UPDATE "recommendations" SET "tmdb_id"=268, "imdb_id"='tt0096895', "igdb_id"=NULL, "title"='Batman', "original_title"='Batman', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rBN6GPKUDZ6ZKAQiEZegZ0DZb6V.jpg', "overview"='Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.4324, "vote_average"=7.233, "is_ambiguous"=0, "evidence_score"=22.573125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=1038;
