UPDATE "recommendations" SET "tmdb_id"=386948, "imdb_id"='tt1623202', "igdb_id"=NULL, "title"='Beautiful Brazil', "original_title"='Beautiful Brazil', "media_type"='movie', "release_year"=1952, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='We start in Rio de Janeiro, with the statue of Cristo Redentor on Mount Corcovado, the avenue along the beach, the beauty of an historic city, and the landmark, Sugarloaf. Brazil''s 47 million people celebrate racial diversity. From the Copacabana, we travel 40 miles to a resort, Quitandinha, where President Truman spoke. Then it''s on to Sao Paulo, a modern, industrial city, and finally to the spectacular waterfalls of Iguazu on the border between Brazil and Argentina.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.1933, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=4.45667441860465132e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=1099;
UPDATE "recommendations" SET "tmdb_id"=15, "imdb_id"='tt0033467', "igdb_id"=NULL, "title"='Citizen Kane', "original_title"='Citizen Kane', "media_type"='movie', "release_year"=1941, "poster_url"='https://image.tmdb.org/t/p/w500/sav0jxhqiH0bPr2vZFU0Kjt2nZL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ruF3Lmd4A8MHbnEBE6lxPMbsHGL.jpg', "overview"='Newspaper magnate Charles Foster Kane is taken from his mother as a boy and made the ward of a rich industrialist. As a result, every well-meaning, tyrannical or self-destructive move he makes for the rest of his life appears in some way to be a reaction to that deeply wounding event.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.2754, "vote_average"=8.0, "is_ambiguous"=0, "evidence_score"=1.3298571428571428e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=1102;
