UPDATE "recommendations" SET "tmdb_id"=8066, "imdb_id"='tt0371257', "igdb_id"=NULL, "title"='Stay', "original_title"='Stay', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/nrLZVP8jG0KBcabahRPp6UP7Oy2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/eUNQJ0XKHoGDDQzj1Y4WhE5zAFJ.jpg', "overview"='Psychiatrist Sam Foster has a new patient, Henry Letham, who claims to be suicidal. In trying to diagnose him, Sam visits Henry''s prior therapist and also finds Henry''s mother -- even though Henry has said that he murdered both of his parents. As reality starts to contradict fact, Sam spirals into an unstable mental state. Then he finds a clue as to how and when Henry may try to kill himself, and races to try to stop him.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2007, "vote_average"=6.639, "is_ambiguous"=0, "evidence_score"=28.3312, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=1446;
