UPDATE "recommendations" SET "tmdb_id"=16373, "imdb_id"='tt0037415', "igdb_id"=NULL, "title"='The Uninvited', "original_title"='The Uninvited', "media_type"='movie', "release_year"=1944, "poster_url"='https://image.tmdb.org/t/p/w500/uwp5ahLmWliRyX3mPoLHU7BKhf5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/poCmeIQA2xL7GnGq9PMwUcJ4AgI.jpg', "overview"='A pair of siblings from London [Ray Milland and Ruth Hussey] purchase a surprisingly affordable, lonely cliff-top house in Cornwall, England. Only to discover that it actually carries a ghostly price, and soon they’re caught up in a bizarre romantic triangle from beyond the grave. Rich in atmosphere, The Uninvited, directed by Lewis Allen, was groundbreaking for the seriousness with which it treated the supernatural, haunted house genre, and it remains an elegant and eerie experience, featuring a classic score by Victor Young. A tragic family past, a mysteriously locked room, cold chills, bumps in the night - this gothic Hollywood classic has it all.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5437, "vote_average"=6.927, "is_ambiguous"=0, "evidence_score"=9.79714285714285715e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-31 03:40:48' WHERE "id"=2480;
