UPDATE "recommendations" SET "tmdb_id"=9266, "imdb_id"='tt0300532', "igdb_id"=NULL, "title"='Blue Crush', "original_title"='Blue Crush', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xsVMKdSndUKid3Xm3Tudf5bcOlv.jpg', "overview"='Nothing gets between Anne Marie and her board. Living in a beach shack with three roommates, she is up before dawn every morning to conquer the waves and count the days until the Pipe Masters competition. Having transplanted herself to Hawaii with no one''s blessing but her own, Anne Marie finds all she needs in the adrenaline-charged surf scene - until pro quarterback Matt Tollman comes along...', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6737, "vote_average"=5.998, "is_ambiguous"=0, "evidence_score"=34.2946875, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-31 03:40:48' WHERE "id"=3451;
