UPDATE "recommendations" SET "tmdb_id"=6964, "imdb_id"='tt0337741', "igdb_id"=NULL, "title"='Something''s Gotta Give', "original_title"='Something''s Gotta Give', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/1cpdqe0SpiHzzbOLq9GDUUlZdSl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xTQXtSQQZY5ZbJ1GxEcSCRP4aWV.jpg', "overview"='When perpetually single, aging music industry exec Harry Sanborn, and his latest trophy girlfriend, Marin, arrive at her mother''s beach house in the Hamptons, they find that her mother, playwright Erica Barry, also plans to stay for the weekend. Erica is scandalized by the relationship and Harry''s sexist ways. But when Harry has a heart attack while there, and the doctor prescribes bedrest, his only option is to stay at the Barry home. Left in the care of Erica and his doctor, a love triangle starts to take shape.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.8293, "vote_average"=6.63, "is_ambiguous"=0, "evidence_score"=15.24875, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-31 03:40:48' WHERE "id"=3925;
