UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=36952, "title"='Wolfenstein II: The New Colossus', "original_title"='Wolfenstein II: The New Colossus', "media_type"='game', "release_year"=2017, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co21c5.jpg', "backdrop_url"=NULL, "overview"='Wolfenstein II: The New Colossus is the eleventh installment of the Wolfenstein series and a sequel to the 2014''s Wolfenstein: The New Order. The game follows the main protagonist, William Joseph "B.J." Blazkowicz, in his efforts to ignite a Second American Revolution.

The game is played from a first-person perspective and most of its levels are navigated on foot. The story is arranged in chapters, which players complete in order to progress. A binary choice in the prologue alters the game''s entire storyline; some characters and small plot points are replaced throughout the timelines. The game features a variety of weapons, most of which can be dual wielded. A cover system is also present.', "external_url"='https://www.igdb.com/games/wolfenstein-ii-the-new-colossus', "platforms"='["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=7.885, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-31 03:40:48' WHERE "id"=4160;
