UPDATE "recommendations" SET "tmdb_id"=26320, "imdb_id"='tt1127896', "igdb_id"=NULL, "title"='Taking Woodstock', "original_title"='Taking Woodstock', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/wIdyAJCvIj3QUoNmmDdnhXpCMpp.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uhPAPblYLrp6UJXi0LdUHPTovkY.jpg', "overview"='The story of Elliot Tiber and his family, who inadvertently played a pivotal role in making the famed Woodstock Music and Arts Festival into the happening that it was. When Elliot hears that a neighboring town has pulled the permit on a hippie music festival, he calls the producers thinking he could drum up some much-needed business for his parents'' run-down motel. Three weeks later, half a million people are on their way to his neighbor’s farm in White Lake, New York, and Elliot finds himself swept up in a generation-defining experience that would change his life–and American culture–forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.4516, "vote_average"=6.197, "is_ambiguous"=0, "evidence_score"=1.07916666666666678e+01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-31 03:40:48' WHERE "id"=5518;
