UPDATE "recommendations" SET "tmdb_id"=2044, "imdb_id"='tt0410297', "igdb_id"=NULL, "title"='The Lake House', "original_title"='The Lake House', "media_type"='movie', "release_year"=2006, "poster_url"='https://image.tmdb.org/t/p/w500/tHpc1118dYWLnHZleGhwZxRbpae.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cvenzPOcYthevmYvy0WX4pZ2RNp.jpg', "overview"='When architect Alex Wyler moves into an unusual glass house on stilts over a lake, he discovers a note from the previous tenant in the mailbox--but no one''s lived in the house for years. He replies and soon discovers that he''s corresponding with a doctor named Kate Forster. Their correspondence, only through the ''magical'' mailbox, turns romantic and their paths cross in unexpected ways, but when they try to truly connect, danger looms. They must try to unravel the mystery behind their extraordinary romance before it''s too late.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.3488, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=9.94833333333333236e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-31 03:40:48' WHERE "id"=6078;
