UPDATE "recommendations" SET "tmdb_id"=6068, "imdb_id"='tt0120828', "igdb_id"=NULL, "title"='Six Days Seven Nights', "original_title"='Six Days Seven Nights', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/fzWrrCzRa16v51TXAUuT6Wendw7.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hgzoUvscb0iQ2M3xaNiBzxG8Ors.jpg', "overview"='In the South Pacific, in Polynesia, on the island of Makatea, Quinn Harris, a taciturn pilot, leads a quiet life, content to earn a living by transporting goods in his De Havilland Beaver. His life is exactly as he wants it to be—until he meets Robin Monroe, a sophisticated and determined woman, the assistant editor of a New York magazine, on vacation for a week with her boyfriend, Frank Martin.  An urgent work assignment in Tahiti, the neighboring island, forces Robin to reluctantly hire Quinn to fly her there. But a violent storm forces them to make an emergency landing on a deserted island. This unlikely pair avoids each other at first, until they are forced to team up to escape the island... and evade the pirates who are after them. Danger and temptation are never far away...', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4423, "vote_average"=6.106, "is_ambiguous"=0, "evidence_score"=6.18, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-31 03:40:48' WHERE "id"=6208;
