UPDATE "recommendations" SET "tmdb_id"=35997, "imdb_id"='tt0320512', "igdb_id"=NULL, "title"='The Smashing Machine', "original_title"='The Smashing Machine', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/xfR7bDx7vh7HqRuZmnaRyMWju87.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5TzPlKBjQNCkli0SZRtwkV8LNM.jpg', "overview"='An unflinching look at the life and story of Mark Kerr between 1999 and 2001, an intelligent, articulate, and emotionally vulnerable athlete, considered by many at the time to be the most dominant ultimate fighter in the world. A former Olympic wrestler, Kerr easily dominated all his opponents, earning him the nickname "The Smashing Machine." With the promise of big money and the euphoria of his early victories, Kerr must battle his injuries and inner fears. The shock of these fights takes a heavy toll on his body and mind, and Kerr attempts to overcome these physical and psychological traumas by turning to painkillers. Kerr''s addiction is shown in its raw form, with the camera capturing him desperately soliciting drugs from friends and staff, and injecting painkillers into his veins. His shocking defeat to Fujita in Japan shows us a story that is sometimes difficult and heartbreaking to watch.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9251, "vote_average"=7.104, "is_ambiguous"=0, "evidence_score"=4.755, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-31 03:40:48' WHERE "id"=9443;
