UPDATE "recommendations" SET "tmdb_id"=49530, "imdb_id"='tt1637688', "igdb_id"=NULL, "title"='In Time', "original_title"='In Time', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pxL08w7Eq0vKrQ3mJzYp0VHGaKG.jpg', "overview"='In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the "time keepers".', "external_url"=NULL, "platforms"=NULL, "popularity"=18.1743, "vote_average"=6.971, "is_ambiguous"=0, "evidence_score"=7.022, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-31 03:40:48' WHERE "id"=9582;
