UPDATE "recommendations" SET "tmdb_id"=118727, "imdb_id"='tt0267675', "igdb_id"=NULL, "title"='The Life & Adventures of Santa Claus', "original_title"='The Life & Adventures of Santa Claus', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/yJRqwoipsVdQE4DJ5YC4D8TxFk9.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7bZgyrUOq1fkjbXVkaNgmcKMQQn.jpg', "overview"='Based on the popular book by L. Frank Baum, the beloved author of The Wonderful Wizard of Oz, comes the incredible story of The Life & Adventures of Santa Claus.  Many centuries ago, long before toys had even been invented, a baby abandoned at the edge of an enchanted forest was adopted and raised by a beautiful wood nymph, thus beginning the life story of Santa Claus. From his first truly magical childhood through the discovery of his life''s work of making children happy, discover the origin of every tradition surrounding Santa Claus, from toys, stockings and lighted trees to reindeer and sleigh. Journey back to a time of magic and wonder, and experience this heartwarming tale that will bring joy each holiday season.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.3796, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=1.16766666666666676e+01, "created_at"='2026-08-27 07:35:55', "updated_at"='2026-08-31 03:40:48' WHERE "id"=12419;
