UPDATE "recommendations" SET "tmdb_id"=10652, "imdb_id"='tt0093137', "igdb_id"=NULL, "title"='Hamburger Hill', "original_title"='Hamburger Hill', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/a84FDoIm64qcyKq6BEMB9Ycldpt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pRpg9OAe4hrThTPxPSPzc185f0D.jpg', "overview"='The men of Bravo Company are facing a battle that''s all uphill… up Hamburger Hill. Fourteen war-weary soldiers are battling for a mud-covered mound of earth so named because it chews up soldiers like chopped meat. They are fighting for their country, their fellow soldiers and their lives. War is hell, but this is worse. Hamburger Hill tells it the way it was, the way it really was. It''s a raw, gritty and totally unrelenting dramatic depiction of one of the fiercest battles of America''s bloodiest war. This happened. Hamburger Hill - war at its worst, men at their best.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.8518, "vote_average"=6.6, "is_ambiguous"=0, "evidence_score"=2.03, "created_at"='2026-08-28 09:15:02', "updated_at"='2026-08-31 03:40:48' WHERE "id"=12534;
